-- The full frequency table, read only when opened. The counts are unlabelled
-- vectors in freq_data; dpd/frequency_layout.lua, generated by
-- tools/gen_frequency_layout.py from DPD's template, places them.
local Json = require("json")
local Frequency = {}
Frequency.__index = Frequency
Frequency.layout = require("dpd/frequency_layout")
Frequency.corpora = {
    { key = "cst", label = "CST", name = "Chaṭṭha Saṅgāyana Tipiṭaka (Myanmar)", columns = { "cst_m", "cst_a", "cst_t" } },
    { key = "bjt", label = "BJT", name = "Buddha Jayanti Tipiṭaka (Sri Lanka)", columns = { "bjt_m", "bjt_a" } },
    { key = "sya", label = "SYA", name = "Syāmaraṭṭha 1927 Royal Edition (Thailand)", columns = { "sya_m", "sya_a" } },
    { key = "sc", label = "MST", name = "Mahāsaṅgīti Tipiṭaka (SuttaCentral)", columns = { "sc_m" } },
}
Frequency.column_labels = { cst_m = "M", cst_a = "A", cst_t = "Ṭ", bjt_m = "M", bjt_a = "A",
    sya_m = "M", sya_a = "A", sc_m = "M" }
local vectors = { cst = "Cst", bjt = "Bjt", sya = "Sya", sc = "Sc" }
local MAX_DATA = 16384
local DAMAGE = "Unreadable DPD frequency data. Replace the database with a fresh DPD mobile download."

function Frequency.new(db) return setmetatable({ db = db }, Frequency) end

--- DPD's ten grades as at most three e-ink emphasis levels: 0 plain, 1 bold,
--- 2 bold on a grey cell.
function Frequency.emphasis(grade)
    grade = tonumber(grade) or 0
    if grade >= 7 then return 2 elseif grade >= 4 then return 1 end
    return 0
end

local function number(value)
    value = tonumber(value)
    return value and value >= 0 and value == math.floor(value) and value or nil
end

--- @return table { heading, only_compounds, sections = { { label, rows = { { label,
---   cells = { [column] = { value, grade, rowspan } } } } } }, error }
function Frequency:table(id)
    local result = { sections = {} }
    local ok = pcall(function()
        local row = self.db:query("SELECT freq_data FROM dpd_headwords WHERE id = ?", { id })[1]
        local raw = row and row.freq_data
        if type(raw) ~= "string" or raw == "" then result.error = "DPD has no frequency data for this entry."; return end
        assert(#raw <= MAX_DATA, DAMAGE)
        local data = Json.decode(raw)
        assert(type(data) == "table" and type(data.FreqHeading) == "string", DAMAGE)
        result.heading = data.FreqHeading
        local counts, grades = {}, {}
        for corpus, prefix in pairs(vectors) do
            counts[corpus], grades[corpus] = data[prefix .. "Freq"], data[prefix .. "Grad"]
            assert(type(counts[corpus]) == "table" and type(grades[corpus]) == "table", DAMAGE)
        end
        if #counts.cst == 0 then result.only_compounds = true; return end
        for _, section in ipairs(Frequency.layout.sections) do
            local out = { label = section.label, rows = {} }
            for _, line in ipairs(section.rows) do
                local cells = {}
                for _, cell in ipairs(line.cells) do
                    local corpus = cell.column:match("^(%a+)_")
                    local value = number(counts[corpus][cell.index])
                    assert(value, DAMAGE)
                    cells[cell.column] = { value = value, grade = number(grades[corpus][cell.index]) or 0,
                        rowspan = cell.rowspan or 1 }
                end
                out.rows[#out.rows + 1] = { label = line.label, cells = cells }
            end
            result.sections[#result.sections + 1] = out
        end
    end)
    if not ok then result = { sections = {}, error = DAMAGE } end
    return result
end

return Frequency
